//                stripes: a list of 5 colours, left to right, or leave as [] for a plain shirt
//    description one sentence about the shirt's look
//    facts       research fields. Leave a field as null until it is verified.
//                manufacturer, debut, story: the facts; each has a ...Source link (storySources is a list).
//                manufacturerNote: shown under the maker, e.g. when sources disagree.
//                wornInFinal, wornAs ("home"/"change"), wornSource, wornNote: the kit worn on the day.
//                Filled from research/ by tools/plug-kit-facts.js; edit research/A1-corrections.json, not here.
//    matches     ids of match cards this shirt appears in (see matches.js)
//    coloursSource  where the colours come from, e.g. 'Wikipedia, "1966 FIFA World Cup final" (revision ...)'.
//                Leave it out if the colours are only the team's usual ones. Write "hand" to stop
//                tools/import-kits.js from changing colours you have set yourself.
//    coloursUrl  link to that source, shown on the shirt's page
//    illustration { file, credit }: a drawing of the full kit in assets/kits/, made by
//                tools/import-kits.js from Wikipedia's kit pictures, with the credit line
//                the pictures' licences ask for. Leave it out to show the flat drawing
//                made from "colours" instead. Write "hand" to keep a drawing you made yourself.
//
//  Do not write a fact you have not checked. null shows as "to be researched".
// ============================================================
